                                /** @description Client-chosen unique id of this element within the document (any non-empty string, e.g. a UUID). */
                                id: string;
                                /** @description Left edge of the element in pixels, measured from the canvas's left edge. */
                                x: number;
                                /** @description Top edge of the element in pixels, measured from the canvas's top edge. */
                                y: number;
                                /** @description Element box width in pixels. */
                                width: number;
                                /** @description Element box height in pixels. */
                                height: number;
                                /**
                                 * @description For `url` image elements: true renders the image per request instead of baking it into the cached static background. Defaults to false.
                                 * @default false
                                 */
                                priority: boolean;
                                /**
                                 * @description Element kind: image.
                                 * @constant
                                 */
                                type: "image";
                                /**
                                 * @description Image source: `url` (fixed image from `url`), `avatarUser` (the contact's profile picture, resolved per request), or `customField` (image URL stored in the contact's custom field `customFieldId`).
                                 * @enum {string}
                                 */
                                imageType: "url" | "avatarUser" | "customField";
