                                replyToNewContactsOnly: boolean;
                                /** @description Reply at most once per commenter on each post. */
                                replyOncePerUserPerPost: boolean;
                                /** @description Also like the comment when replying (where the channel supports likes). */
                                likeUserComment: boolean;
                                /** @description When false, skip commenters this automation already replied to on a different post. */
                                replyToUsersWhoCommentedOnOtherPosts: boolean;
                                /** @description Ignore replies to other comments; only react to top-level comments. */
                                ignoreCommentReplies: boolean;
