                        /** @description The discount code the order used, kept if the code is deleted. */
                        discountCode: string | null;
                        /** @description What the customer pays. */
                        total: number;
                        contactId: string | null;
                        conversationId: string | null;
                        inboxId: string | null;
                        channel: string | null;
                        customerName: string | null;
                        customerEmail: string | null;
                        customerPhone: string | null;
                        shippingType: ("delivery" | "pickup") | null;
                        shippingAddress: {
                            line1?: string | null;
                            line2?: string | null;
                            city?: string | null;
                            state?: string | null;
                            zip?: string | null;
                            country?: string | null;
                        } | null;
