                        acceptedAt: string | null;
                        shippedAt: string | null;
                        concludedAt: string | null;
                        cancelledAt: string | null;
                        /** @description The store's order id, for an order mirrored from a connected store: Shopify's order GID (`source: shopify`) or the WooCommerce site and order id such as `example.com#1234` (`source: woocommerce`). */
                        externalId: string | null;
                        /** @description The store's order name or number, e.g. `#1004`. */
                        externalName: string | null;
                        /** @description The mirrored store's fulfillment state; null for our own orders. */
                        fulfillmentStatus: ("unfulfilled" | "partial" | "fulfilled") | null;
                        trackingCompany: string | null;
                        trackingNumber: string | null;
                        trackingUrl: string | null;
                        /** Format: date-time */
